const CITIES=[['Delhi',28.6139,77.209,'Days 1 & 4 · 27 & 30 Nov'],['Amritsar',31.6340,74.8723,'Day 3 · 29 Nov · Golden Temple / Wagah'],['Mohali',30.7046,76.7179,'Day 2 · 28 Nov · CU Gharuan'],['Kolkata',22.5726,88.3639,'Home, for comparison']];
function aqiCat(v){return v==null?['No data','#999','']:v<=50?['Good','#3a9d5d','Fine for all outdoor plans']:v<=100?['Moderate','#c9a200','OK for most; sensitive people take care']:v<=150?['Unhealthy for sensitive groups','#e8873a','Limit long outdoor stretches; carry a mask']:v<=200?['Unhealthy','#d64545','Wear an N95/FFP2 mask outdoors']:v<=300?['Very unhealthy','#8f3f97','Mask essential; keep outdoor time short']:['Hazardous','#7e0023','Avoid long outdoor exposure; mask essential']}
function paintAQI(){document.querySelectorAll('.aqi-line').forEach(el=>{const a=AQ[el.dataset.city];if(!a){el.textContent='Air quality ('+el.dataset.city+'): not loaded (offline?). See the AQI section.';return}const c=aqiCat(a.now);el.innerHTML='<b>Air quality, '+el.dataset.city+':</b> <span style="color:'+c[1]+';font-weight:700">AQI '+(a.now==null?'n/a':Math.round(a.now))+' · '+c[0]+'</span> <span class="small">(now, model estimate). '+c[2]+'</span>'})}
async function loadAQI(){const box=$('aqibox');let html='';const saved=S('aqic')||{};
for(const [n,la,lo,when] of CITIES){let r=null;const base='https://air-quality-api.open-meteo.com/v1/air-quality?latitude='+la+'&longitude='+lo+'&timezone=Asia%2FKolkata&current=us_aqi,pm2_5';
try{let j=null;try{const x=await fetch(base+'&hourly=us_aqi&start_date=2026-11-27&end_date=2026-11-30');if(x.ok)j=await x.json()}catch(e){}
if(!j){const x=await fetch(base);j=await x.json()}
const days={};if(j.hourly&&j.hourly.time)j.hourly.time.forEach((t,i)=>{const v=j.hourly.us_aqi[i];if(v!=null){const d=t.slice(8,10);days[d]=Math.max(days[d]||0,v)}});
r={now:j.current?j.current.us_aqi:null,pm:j.current?j.current.pm2_5:null,at:j.current?j.current.time:'',days};saved[n]=r}catch(e){r=saved[n]||null}
AQ[n]=r;const c=aqiCat(r&&r.now);const dk=r&&r.days?Object.keys(r.days):[];
html+='<div class="card aqi-card" style="border-top:5px solid '+c[1]+'"><h3>'+n+'</h3><div class="small">'+when+'</div><div class="aqi-num" style="color:'+c[1]+'">'+(r&&r.now!=null?Math.round(r.now):'–')+'</div><div><b>'+c[0]+'</b></div><div class="small">'+c[2]+(r&&r.pm!=null?' · PM2.5 '+Math.round(r.pm)+' µg/m³':'')+(r&&r.at?'<br>as of '+r.at.replace('T',' '):'')+'</div>'+(dk.length?'<div class="aqi-days">'+['27','28','29','30'].map(d=>'<span style="background:'+aqiCat(r.days[d])[1]+'">'+d+' Nov: '+(r.days[d]==null?'–':'max '+Math.round(r.days[d]))+'</span>').join('')+'</div>':'<div class="small" style="margin-top:8px">Trip-date forecast is not available yet (models cover only a few days ahead). Re-check 3–4 days before.</div>')+'</div>'}
S('aqic',saved);box.innerHTML=html;paintAQI()}
loadAQI();

/* AQI v2: Indian (CPCB) scale + manual official reading */
function cpcb(v){return v==null?['No data','#999','']:v<=50?['Good','#3a9d5d','Fine for all outdoor plans']:v<=100?['Satisfactory','#7fb239','Minor discomfort for sensitive people']:v<=200?['Moderate','#c9a200','Discomfort for lung/heart patients']:v<=300?['Poor','#e8873a','Wear a mask; limit long outdoor stretches']:v<=400?['Very Poor','#d64545','N95/FFP2 mask outdoors; keep outdoor time short']:['Severe','#7e0023','Avoid long outdoor exposure; N95/FFP2 essential; prefer indoor stops, metro and cabs']}
function pm25ToIN(p){const B=[[0,30,0,50],[30,60,50,100],[60,90,100,200],[90,120,200,300],[120,250,300,400],[250,500,400,500]];for(const [a,b,c,d] of B)if(p<=b)return Math.round(c+(p-a)*(d-c)/(b-a));return 500}
MAN=S('aqiman2')||{};
function aqiVal(n){if(MAN[n]!=null)return [MAN[n],'your official reading'];const a=AQ[n];return a&&a.pm!=null?[pm25ToIN(a.pm),'model estimate, can under-read']:[null,'']}
function paintAQI(){document.querySelectorAll('.aqi-line').forEach(el=>{const n=el.dataset.city,[v,src]=aqiVal(n);if(v==null){el.textContent='Air quality ('+n+'): not loaded (offline?). See the AQI section.';return}const c=cpcb(v);el.innerHTML='<b>Air quality, '+n+':</b> <span style="color:'+c[1]+';font-weight:700">AQI '+v+' · '+c[0]+'</span> <span class="small">('+src+'). '+c[2]+'</span>'})}
function setMan(n,v){if(v===''||isNaN(+v))delete MAN[n];else MAN[n]=Math.round(+v);S('aqiman2',MAN);renderAQI()}
function renderAQI(){$('aqibox').innerHTML=CITIES.map(([n,,,when])=>{const [v,src]=aqiVal(n),c=cpcb(v),a=AQ[n];return '<div class="card aqi-card" style="border-top:5px solid '+c[1]+'"><h3>'+n+'</h3><div class="small">'+when+'</div><div class="aqi-num" style="color:'+c[1]+'">'+(v==null?'–':v)+'</div><div><b>'+c[0]+'</b> <span class="small">(Indian CPCB scale)</span></div><div class="small">'+c[2]+'<br>Source: '+src+(a&&a.pm!=null?'<br>Model: PM2.5 '+Math.round(a.pm)+' µg/m³ · US AQI '+Math.round(a.now)+(a.at?' · '+a.at.replace('T',' '):''):'')+'</div><label class="small" style="display:block;margin-top:10px">Official AQI today (CPCB / aqi.in)<br><input type="number" min="0" max="999" value="'+(MAN[n]!=null?MAN[n]:'')+'" placeholder="e.g. 450" onchange="setMan(\''+n+'\',this.value)"></label></div>'}).join('');paintAQI()}
async function loadAQI(){const saved=S('aqic2')||{};for(const [n,la,lo] of CITIES){try{const x=await fetch('https://air-quality-api.open-meteo.com/v1/air-quality?latitude='+la+'&longitude='+lo+'&timezone=Asia%2FKolkata&current=us_aqi,pm2_5');const j=await x.json();AQ[n]={now:j.current.us_aqi,pm:j.current.pm2_5,at:j.current.time};saved[n]=AQ[n]}catch(e){AQ[n]=saved[n]||null}}S('aqic2',saved);renderAQI()}
renderAQI();loadAQI();

/* AQI v3: ranges + defaults you reported on 20 Nov */
function parseA(v){const m=String(v).match(/(\d+)\s*(?:-|–|to)\s*(\d+)/);if(m){const lo=+m[1],hi=+m[2];return {mid:Math.round((lo+hi)/2),txt:lo+'–'+hi}}const n=parseInt(v);return isNaN(n)?null:{mid:n,txt:String(n)}}
function aqiVal(n){if(!DEFA)return [null,'',null];const p=MAN[n]!=null?parseA(MAN[n]):null;if(p)return [p.mid,'your reading (20 Nov)',p.txt];const a=AQ[n];return a&&a.pm!=null?[pm25ToIN(a.pm),'model estimate, can under-read',String(pm25ToIN(a.pm))]:[null,'',null]}
function paintAQI(){document.querySelectorAll('.aqi-line').forEach(el=>{const n=el.dataset.city,[v,src,t]=aqiVal(n);if(v==null){el.textContent='Air quality ('+n+'): not loaded (offline?). See the AQI section.';return}const c=cpcb(v);el.innerHTML='<b>Air quality, '+n+':</b> <span style="color:'+c[1]+';font-weight:700">AQI '+t+' · '+c[0]+'</span> <span class="small">('+src+'). '+c[2]+'</span>'})}
function setMan(n,v){if(v===''||!parseA(v))delete MAN[n];else MAN[n]=String(v).trim();S('aqiman2',MAN);renderAQI()}
function renderAQI(){$('aqibox').innerHTML=CITIES.map(([n,,,when])=>{const [v,src,t]=aqiVal(n),c=cpcb(v),a=AQ[n];return '<div class="card aqi-card" style="border-top:5px solid '+c[1]+'"><h3>'+n+'</h3><div class="small">'+when+'</div><div class="aqi-num" style="color:'+c[1]+'">'+(t==null?'–':t)+'</div><div><b>'+c[0]+'</b> <span class="small">(Indian CPCB scale)</span></div><div class="small">'+c[2]+'<br>Source: '+src+(a&&a.pm!=null?'<br>Model: PM2.5 '+Math.round(a.pm)+' µg/m³':'')+'</div><label class="small" style="display:block;margin-top:10px">Official AQI today (e.g. 450 or 400-600)<br><input type="text" style="width:130px;background:var(--bg);border:1.5px solid var(--ink);padding:6px" value="'+(MAN[n]!=null?MAN[n]:'')+'" placeholder="CPCB / aqi.in" onchange="setMan(\''+n+'\',this.value)"></label></div>'}).join('');paintAQI()}
MAN=Object.assign({Delhi:'400-600',Kolkata:'120-170',Chandigarh:'120-150',Mohali:'150-170'},S('aqiman2')||{});
renderAQI();

/* AQI v4: aqi.in (AQI-US) scale, cartoon characters, weather */
function cpcb(v){return v==null?['No data','#999','']:v<=50?['Good','#3a9d5d','Fine for all outdoor plans']:v<=100?['Moderate','#c9a200','OK for most; sensitive people take care']:v<=150?['Poor','#e8873a','Sensitive groups limit long outdoor time; carry a mask']:v<=200?['Unhealthy','#d64545','Wear an N95/FFP2 mask outdoors']:v<=300?['Severe','#8f3f97','N95/FFP2 essential; keep outdoor time short; prefer indoor stops']:['Hazardous','#7e0023','Avoid long outdoor exposure; N95/FFP2 essential']}
var DET={Amritsar:{pm:'–',p10:'–',t:'–',c:'Loads when online',h:'–',w:'–',uv:'–'},Delhi:{pm:195,p10:273,t:25,c:'Sunny',h:38,w:3.6,uv:4.4},Chandigarh:{pm:45,p10:59,t:25,c:'Smoky haze',h:35,w:3.6,uv:4.1},Mohali:{pm:62,p10:81,t:24,c:'Smoky haze',h:37,w:3.6,uv:3.9},Kolkata:{pm:19,p10:25,t:23,c:'Rain',h:96,w:10.1,uv:0.6}};
var WX={};
function wcode(c){return c==null?null:c==0?'Clear':c<=3?'Partly cloudy':c<=48?'Fog / haze':c<=67?'Rain':c<=77?'Snow':c<=82?'Showers':'Thunderstorm'}
function person(v){const L=v==null||v<=50?0:v<=100?1:v<=150?2:v<=200?3:v<=300?4:5,sh=['#3a9d5d','#c9a200','#e8873a','#d64545','#8f3f97','#7e0023'][L];
let f='<svg viewBox="0 0 80 100" width="70" height="88" aria-hidden="true"><rect x="14" y="68" width="52" height="34" rx="15" fill="'+sh+'"/><rect x="34" y="58" width="12" height="12" fill="#e9b98a"/><circle cx="40" cy="38" r="22" fill="#f1c9a0"/><path d="M18 38a22 21 0 0144 0q-10-13-22-13t-22 13z" fill="#2b2118"/>';
if(L<=1)f+='<circle cx="32" cy="40" r="2.4" fill="#222"/><circle cx="48" cy="40" r="2.4" fill="#222"/>';else f+='<path d="M28 40h8M44 40h8" stroke="#222" stroke-width="2.6" stroke-linecap="round"/>';
if(L>=4)f+='<path d="M27 33l9 3M53 33l-9 3" stroke="#2b2118" stroke-width="2.4"/>';
if(L==0)f+='<path d="M32 49q8 7 16 0" stroke="#222" stroke-width="2.4" fill="none"/>';
if(L==1)f+='<path d="M33 52h14" stroke="#222" stroke-width="2.4"/>';
if(L==2)f+='<circle cx="40" cy="52" r="8" fill="#e9b98a" stroke="#c99a6e"/><path d="M52 44l8-3M54 52h8M52 58l7 4" stroke="#8a96a3" stroke-width="2"/>';
if(L>=3)f+='<path d="M24 45h32v10q-16 10-32 0z" fill="#fff" stroke="#b8c0c8" stroke-width="1.5"/><path d="M24 47l-6-4M56 47l6-4" stroke="#b8c0c8" stroke-width="1.5"/>';
if(L>=4)f+='<path d="M63 28q5 7 0 11q-5-4 0-11z" fill="#6cc3ee"/>';
if(L==5)f+='<path d="M8 18q7-8 12 0q-5 8-12 0" stroke="#7e0023" stroke-width="2" fill="none"/>';
return f+'</svg>'}
function parseA(v){const m=String(v).match(/(\d+)\s*(?:-|–|to)\s*(\d+)/);if(m){const lo=+m[1],hi=+m[2];return {mid:Math.round((lo+hi)/2),txt:lo+'–'+hi}}const n=parseInt(v);return isNaN(n)?null:{mid:n,txt:String(n)}}
function aqiVal(n){const p=MAN[n]!=null?parseA(MAN[n]):null;if(p)return [p.mid,(MAN[n]==DEFA[n]?'aqi.in, 20 Nov 12:01':'your reading'),p.txt];const a=AQ[n];return a&&a.now!=null?[Math.round(a.now),'live model estimate (may differ)',String(Math.round(a.now))]:[null,'',null]}
var DEFA={Delhi:'278',Chandigarh:'124',Mohali:'156',Kolkata:'70'};
MAN=Object.assign({},DEFA,S('aqiman3')||{});
function setMan(n,v){if(v===''||!parseA(v))delete MAN[n];else MAN[n]=String(v).trim();S('aqiman3',MAN);renderAQI()}
function renderAQI(){if(!DET||!DEFA)return;$('aqibox').innerHTML=CITIES.map(([n,,,when])=>{const [v,src,t]=aqiVal(n),c=cpcb(v),d=DET[n],w=WX[n]||{},tt=w.t!=null?Math.round(w.t):d.t,cc=w.c||d.c,hh=w.h!=null?Math.round(w.h):d.h,ww=w.w!=null?(Math.round(w.w*10)/10):d.w,uv=w.uv!=null?Math.round(w.uv*10)/10:d.uv;
return '<div class="card aqi-card" style="border-top:5px solid '+c[1]+'"><div class="aqi-top"><div><h3>'+n+'</h3><div class="small">'+when+'</div><div class="aqi-num" style="color:'+c[1]+'">'+(t==null?'–':t)+'</div><b style="color:'+c[1]+'">'+c[0]+'</b> <span class="small">AQI-US</span></div>'+person(v)+'</div><div class="small" style="margin-top:6px">'+c[2]+'<br>PM2.5 '+(MAN[n]==DEFA[n]?d.pm:'–')+' · PM10 '+(MAN[n]==DEFA[n]?d.p10:'–')+' µg/m³ · '+src+'</div><div class="wx"><b>'+tt+'°C</b> '+cc+'<br><span>💧 '+hh+'% · 💨 '+ww+' km/h · UV '+uv+'</span></div><label class="small" style="display:block;margin-top:8px">Update AQI<br><input type="text" style="width:110px;background:var(--bg);border:1.5px solid var(--ink);padding:5px" value="'+(MAN[n]!=null?MAN[n]:'')+'" placeholder="aqi.in" onchange="setMan(\''+n+'\',this.value)"></label></div>'}).join('');paintAQI()}
async function loadWX(){for(const [n,la,lo] of CITIES){try{const j=await(await fetch('https://api.open-meteo.com/v1/forecast?latitude='+la+'&longitude='+lo+'&timezone=Asia%2FKolkata&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code,uv_index')).json();const c=j.current;WX[n]={t:c.temperature_2m,h:c.relative_humidity_2m,w:c.wind_speed_10m,uv:c.uv_index,c:wcode(c.weather_code)}}catch(e){}}renderAQI()}



/* AQI v5: live auto-refresh. Order: aqi.in (via CORS proxy) -> Open-Meteo live model -> cached -> 20 Nov snapshot */
const AQIIN={Delhi:'delhi',Chandigarh:'chandigarh',Mohali:'punjab/mohali',Amritsar:'punjab/amritsar',Kolkata:'west-bengal/kolkata'};
const PROXY=[u=>'https://api.allorigins.win/raw?url='+encodeURIComponent(u),u=>'https://corsproxy.io/?'+encodeURIComponent(u)];
function tmo(ms){const c=new AbortController();setTimeout(()=>c.abort(),ms);return c.signal}
async function fromAqiIn(n){
const u='https://www.aqi.in/in/dashboard/india/'+AQIIN[n];
for(const p of PROXY){try{
const r=await fetch(p(u),{signal:tmo(9000)});if(!r.ok)continue;
const t=(await r.text()).replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ');
const m=t.match(/Live AQI\s*(\d{1,3})\s*\(?\s*AQI-US/i);if(!m)continue;
const d=t.match(/Last Updated:\s*(\d{4})-(\d\d)-(\d\d)/i);if(!d)continue;
if(Date.now()-new Date(+d[1],d[2]-1,+d[3]).getTime()>2*864e5)continue; /* reject stale cached pages */
const a=t.match(/PM2\.5\s*:?\s*(\d+)/i),b=t.match(/pm10\s*:?\s*(\d+)/i),tm=t.match(/Last Updated:\s*[\d-]+\s+([\d:]+\s*[AP]M)/i);
return {v:+m[1],pm:a?+a[1]:null,p10:b?+b[1]:null,src:'aqi.in live',at:tm?tm[1]:''}
}catch(e){}}
return null}
async function fromModel(la,lo){try{const j=await(await fetch('https://air-quality-api.open-meteo.com/v1/air-quality?latitude='+la+'&longitude='+lo+'&timezone=Asia%2FKolkata&current=us_aqi,pm2_5,pm10',{signal:tmo(9000)})).json();const c=j.current;if(!c||c.us_aqi==null)return null;return {v:Math.round(c.us_aqi),pm:c.pm2_5!=null?Math.round(c.pm2_5):null,p10:c.pm10!=null?Math.round(c.pm10):null,src:'live model (Open-Meteo), may differ from aqi.in',at:(c.time||'').slice(11)}}catch(e){return null}}
var busy=false;
async function refreshLive(){if(busy)return;busy=true;const st=$('aqistat');if(st)st.textContent='Refreshing…';
await Promise.all(CITIES.map(async([n,la,lo])=>{const r=(await fromAqiIn(n))||(await fromModel(la,lo));if(r){r.fetched=Date.now();LIVE[n]=r}}));
S('aqilive',LIVE);LIVE_AT=Date.now();busy=false;renderAQI()}
function aqiVal(n){const m=MAN2[n]!=null?parseA(MAN2[n]):null;if(m)return [m.mid,'your reading',m.txt];
const l=LIVE[n];if(l){const old=Date.now()-(l.fetched||0)>1800e3;return [l.v,l.src+(l.at?' · '+l.at:'')+(old?' · cached':''),String(l.v)]}
const f=(typeof DEFA!='undefined'&&DEFA)?DEFA[n]:null;return f!=null?[+f,'offline: saved aqi.in snapshot, 20 Nov 12:01',String(f)]:[null,'',null]}
function setMan(n,v){if(v===''||!parseA(v))delete MAN2[n];else MAN2[n]=String(v).trim();S('aqiman4',MAN2);renderAQI()}
function renderAQI(){if(typeof DET=='undefined'||!DET||!$('aqibox'))return;
$('aqibox').innerHTML=CITIES.map(([n,,,when])=>{const [v,src,t]=aqiVal(n),c=cpcb(v),d=DET[n],w=WX[n]||{},l=LIVE[n],man=MAN2[n]!=null&&parseA(MAN2[n]);
const tt=w.t!=null?Math.round(w.t):d.t,cc=w.c||d.c,hh=w.h!=null?Math.round(w.h):d.h,ww=w.w!=null?(Math.round(w.w*10)/10):d.w,uv=w.uv!=null?Math.round(w.uv*10)/10:d.uv;
const pm=man?'–':l?(l.pm!=null?l.pm:'–'):d.pm,p10=man?'–':l?(l.p10!=null?l.p10:'–'):d.p10;
return '<div class="card aqi-card" style="border-top:5px solid '+c[1]+'"><div class="aqi-top"><div><h3>'+n+'</h3><div class="small">'+when+'</div><div class="aqi-num" style="color:'+c[1]+'">'+(t==null?'–':t)+'</div><b style="color:'+c[1]+'">'+c[0]+'</b> <span class="small">AQI-US</span></div>'+person(v)+'</div><div class="small" style="margin-top:6px">'+c[2]+'<br>PM2.5 '+pm+' · PM10 '+p10+' µg/m³ · '+src+'</div><div class="wx"><b>'+tt+'°C</b> '+cc+'<br><span>💧 '+hh+'% · 💨 '+ww+' km/h · UV '+uv+'</span></div><label class="small" style="display:block;margin-top:8px">Override AQI (optional, clear = live)<br><input type="text" style="width:110px;background:var(--bg);border:1.5px solid var(--ink);padding:5px" value="'+(MAN2[n]!=null?MAN2[n]:'')+'" placeholder="auto" onchange="setMan(\''+n+'\',this.value)"></label></div>'}).join('');
const st=$('aqistat');if(st){const k=CITIES.filter(([n])=>LIVE[n]&&LIVE[n].src=='aqi.in live').length;st.textContent=LIVE_AT?('Auto-refresh every 10 min · checked '+new Date(LIVE_AT).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+' · '+k+'/'+CITIES.length+' cities from aqi.in'+(CITIES.some(([n])=>LIVE[n]&&LIVE[n].src!='aqi.in live')?', rest from live model':'')+(CITIES.every(([n])=>!LIVE[n])?' (offline: showing saved snapshot)':'')):'Auto-refresh every 10 min'}
paintAQI()}
renderAQI();loadWX();refreshLive();
setInterval(refreshLive,600000);setInterval(loadWX,600000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-LIVE_AT>300000)refreshLive()});
